// Cloud Files VM watcher bundle: images/cloudbite-computer/files-watch.py → src/cloudbite-computer-files-watch-source.ts.
//   node tools/build-cloudbite-files-watch.mjs          rebuild
//   node tools/build-cloudbite-files-watch.mjs --check  fail unless the generated file is byte-identical to a fresh build
// Root integration uploads FILES_WATCH_SOURCE verbatim next to the agent; the text is the LF-normalized Python source
// (the repo stores it with eol=lf), so the bundle and its SHA-256 do not depend on the checkout's line endings.
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('../', import.meta.url));
const SOURCE = 'images/cloudbite-computer/files-watch.py';
const OUT = 'src/cloudbite-computer-files-watch-source.ts';
const MAX_BYTES = 256 * 1024;  // same bound as FILES_BRIDGE_LIMITS.agentSourceBytes
const fail = (msg) => { console.error(`build-cloudbite-files-watch: ${msg}`); process.exit(1); };

const text = readFileSync(root + SOURCE, 'utf8').replace(/\r\n/g, '\n');
const bytes = Buffer.byteLength(text, 'utf8');
if (!text.startsWith('#!/usr/bin/env python3\n')) fail(`${SOURCE} must start with the python3 shebang`);
if (bytes > MAX_BYTES) fail(`${SOURCE} is ${bytes} bytes (> ${MAX_BYTES})`);
const sha = createHash('sha256').update(text, 'utf8').digest('hex');

const out = `// GENERATED by tools/build-cloudbite-files-watch.mjs from ${SOURCE} — do not edit.
// Check: node tools/build-cloudbite-files-watch.mjs --check
export const FILES_WATCH_SOURCE_SHA256 = '${sha}';
export const FILES_WATCH_SOURCE_BYTES = ${bytes};
export const FILES_WATCH_SOURCE: string = ${JSON.stringify(text)};
`;

if (process.argv.includes('--check')) {
  let current = null;
  try { current = readFileSync(root + OUT, 'utf8'); } catch { /* missing */ }
  if (current !== out) fail(`${OUT} is stale — run node tools/build-cloudbite-files-watch.mjs`);
  console.log(`build-cloudbite-files-watch: ${OUT} up to date (${bytes} bytes, sha256 ${sha})`);
} else {
  writeFileSync(root + OUT, out);
  console.log(`build-cloudbite-files-watch: wrote ${OUT} (${bytes} bytes, sha256 ${sha})`);
}
